import i18n from '@dhis2/d2-i18n'
import { SingleSelectFieldFF } from '@dhis2/ui'
import React from 'react'
import { useField } from 'react-final-form'
import { Report } from '../types'
import { usePeriodType } from '../../../../context'

export const ParametersSelector = ({ report }: { report: Report }) => {
    const [, setPeriodType] = usePeriodType()
    if (!report) {
        return null
    }
    const availablePeriods = Object.entries(report.relativePeriods)
        .filter(([key, value]) => value)
        .map(([key]) => ({ value: key, label: key }))
    const { input: periodTypeInput, meta: periodTypeMeta } = useField(
        'periodType',
        {
            subscription: { value: true },
        }
    )
    const modifiedInput = {
        ...periodTypeInput,
        onChange: (value: string) => {
            setPeriodType(value)
            periodTypeInput.onChange(value)
        },
    }
    return (
        <>
            {report.reportParams.reportingPeriod && (
                <>
                    <SingleSelectFieldFF
                        inputWidth="250px"
                        name="periodType"
                        dataTest="standardReport-periodTypeSelector"
                        label={i18n.t('Period type')}
                        options={availablePeriods}
                        input={modifiedInput}
                        meta={periodTypeMeta}
                        required
                        clearable
                    />
                </>
            )}
        </>
    )
}
