import { createContext } from 'react'

export type User = {
    id: string
    authorities: string[]
    organisationUnits: string[]
    dataViewOrganisationUnits: string[]
}

type UserContextValue = {
    canAdd: boolean
    canDelete: boolean
    organisationUnits: string[]
    refetchUser: (...args: any[]) => unknown
    keyUiLocale: string
}

const DEFAULT_VALUE: UserContextValue = {
    canAdd: false,
    canDelete: false,
    organisationUnits: [],
    refetchUser: () => {
        console.log('Not implemented')
    },
    keyUiLocale: 'en',
}

/*
 * The DHIS2 platform shell loads this whole app as a dynamic-import chunk
 * (`React.lazy(() => import('./D2App/App.tsx'))` in the shell's App.jsx).
 * In this dev setup that chunk can be evaluated more than once in the same
 * page session, so a plain `createContext()` call here can produce more
 * than one distinct context object — a Provider bound to one evaluation and
 * a consumer bound to another end up with different objects, and the
 * consumer silently falls back to the default value above instead of the
 * Provider's, with no error or warning. (Same issue, same fix, as
 * reports-context.ts before it was replaced by the useReports hook.)
 *
 * Keying the context off `globalThis` makes every evaluation of this module
 * share one object: whichever evaluation runs first creates it, and every
 * later evaluation reuses that same one instead of creating a second.
 */
const GLOBAL_KEY = '__dhis2ReportsAppUserContext__'
const globalScope = globalThis as any

const UserContext =
    globalScope[GLOBAL_KEY] ??
    (globalScope[GLOBAL_KEY] = createContext<UserContextValue>(DEFAULT_VALUE))

export { UserContext }
